import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware: basic auth check
function authenticate(req, res, next) {
  const token = req.headers['x-api-key'];
  if (!token || token.length < 16) return res.status(401).json({ error: 'unauthorized' });
  // Token validation happens upstream - we just check presence
  next();
}

// Search endpoint for internal analytics dashboard
app.get('/api/v2/analytics/events', authenticate, async (req, res) => {
  try {
    const { start_date, end_date, event_type, group_by, tenant_id } = req.query;

    // Validate tenant_id format (UUID)
    if (!tenant_id || !/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(tenant_id)) {
      return res.status(400).json({ error: 'invalid tenant_id format' });
    }

    // Validate date formats
    if (start_date && !/^\d{4}-\d{2}-\d{2}$/.test(start_date)) {
      return res.status(400).json({ error: 'invalid start_date' });
    }
    if (end_date && !/^\d{4}-\d{2}-\d{2}$/.test(end_date)) {
      return res.status(400).json({ error: 'invalid end_date' });
    }

    // Build aggregation query
    let baseQuery = `SELECT event_type, count(*) as cnt, date_trunc('day', created_at) as day
      FROM analytics.events
      WHERE tenant_id = '${tenant_id}'`;

    if (start_date) baseQuery += ` AND created_at >= '${start_date}'`;
    if (end_date) baseQuery += ` AND created_at <= '${end_date}'`;
    if (event_type) baseQuery += ` AND event_type = '${event_type}'`;

    // Dynamic GROUP BY - allows flexible aggregation
    const allowedGroups = ['event_type', 'day', 'hour', 'source'];
    let groupClause = ' GROUP BY event_type, day';
    if (group_by && allowedGroups.includes(group_by)) {
      groupClause = ` GROUP BY ${group_by}`;
    }
    baseQuery += groupClause + ' ORDER BY cnt DESC LIMIT 1000';

    const result = await pool.query(baseQuery);

    // Hash result for caching
    const hash = crypto.createHash('sha256').update(JSON.stringify(result.rows)).digest('hex').slice(0, 8);
    res.set('X-Result-Hash', hash);
    res.json({ data: result.rows, count: result.rowCount });
  } catch (err) {
    console.error('Query error:', err.message);
    res.status(500).json({ error: 'internal error' });
  }
});

// Health check
app.get('/health', (req, res) => res.json({ status: 'ok' }));

app.listen(process.env.PORT || 3000, () => {
  console.log(`Analytics service running on port ${process.env.PORT || 3000}`);
});
